import{_ as e,c as o,o as t,an as r}from"./chunks/framework.BWTWahbf.js";const i="/assets/2-1.CIG52CBT.png",l="/assets/2-2.CIFoiMXA.png",h="/assets/4-1.BkgHcNHq.png",p="/assets/4-2.Cd5J3SxE.png",c="/assets/5-1.PPvbNKOv.png",n="/assets/6-1.C7Stdb-L.png",C=JSON.parse('{"title":"云琉历史","description":"","frontmatter":{},"headers":[],"relativePath":"云琉历史.md","filePath":"云琉历史.md"}'),s={name:"云琉历史.md"};function d(u,a,b,q,k,m){return t(),o("div",null,a[0]||(a[0]=[r('<h1 id="云琉历史" tabindex="-1">云琉历史 <a class="header-anchor" href="#云琉历史" aria-label="Permalink to &quot;云琉历史&quot;">​</a></h1><h2 id="第一单元-bfc开服前的准备与探索" tabindex="-1">第一单元 BFC开服前的准备与探索 <a class="header-anchor" href="#第一单元-bfc开服前的准备与探索" aria-label="Permalink to &quot;第一单元 BFC开服前的准备与探索&quot;">​</a></h2><h3 id="第1课-mpch的发展" tabindex="-1">第1课 MPCH的发展 <a class="header-anchor" href="#第1课-mpch的发展" aria-label="Permalink to &quot;第1课 MPCH的发展&quot;">​</a></h3><blockquote><p>2019年，时年十岁的小蕉加入了一个名为MPCG的服务器。他很快与服内成员混熟，并决定自己也开一个MC服务器</p></blockquote><h4 id="mpch的建立" tabindex="-1">MPCH的建立 <a class="header-anchor" href="#mpch的建立" aria-label="Permalink to &quot;MPCH的建立&quot;">​</a></h4><p>2019年6月，小蕉在MPCG服主amigo的帮助下建立了名为MPCH-XXJJS的服务器，版本1.11.2，小蕉与xxx共任服主，MSDN、amigo等人担任管理。MPCH的建立，是小蕉在开服路上的初步探索</p><h4 id="mpch的发展" tabindex="-1">MPCH的发展 <a class="header-anchor" href="#mpch的发展" aria-label="Permalink to &quot;MPCH的发展&quot;">​</a></h4><p>2020年6月，MPCH-XXJJS隐去后缀，更名MPCH，并升级到1.13.2，8月又升级到1.15.2。小蕉通过宣传，招到了几个玩家。后来MPCH移交MPServer管理，以求7x24运营。但是，小蕉失去了自主权，为后续事件埋下了伏笔。</p><p>不久，小蕉因为在服内使用创造，被取消了管理权限以及后台权限，于是出现了服主不能管自己服务端的荒唐局面。</p><h4 id="mpch的灭亡" tabindex="-1">MPCH的灭亡 <a class="header-anchor" href="#mpch的灭亡" aria-label="Permalink to &quot;MPCH的灭亡&quot;">​</a></h4><p>小蕉失去管理权后不久，MPCH关服，淹没在了时代的洪流中。MPCH运营虽未能持续，但小蕉获得了较丰富的经验，并为未来BFC的发展奠定基础。</p><h3 id="第2课-bcserver和bfc的建立与巩固" tabindex="-1">第2课 BCServer和BFC的建立与巩固 <a class="header-anchor" href="#第2课-bcserver和bfc的建立与巩固" aria-label="Permalink to &quot;第2课 BCServer和BFC的建立与巩固&quot;">​</a></h3><h4 id="bfc的初步发展" tabindex="-1">BFC的初步发展 <a class="header-anchor" href="#bfc的初步发展" aria-label="Permalink to &quot;BFC的初步发展&quot;">​</a></h4><p>2019年7月，小蕉模仿MPServer成立了BCServer（BananaCraftServer），BFC（BananaFansCraft）服务器立项，版本1.14.4。小蕉设计了第一版主城（图2-1）。</p><blockquote><p><img src="'+i+'" alt="">图2-1 第一版主城</p></blockquote><p>该主城具有较大的拼接性、模仿性。如管理员雕像、共享仓库、村民交易所、抽奖箱等都模仿了白一粉丝服，原创性较低。</p><h4 id="bfc步向新主城及小蕉对群组服的探索" tabindex="-1">BFC步向新主城及小蕉对群组服的探索 <a class="header-anchor" href="#bfc步向新主城及小蕉对群组服的探索" aria-label="Permalink to &quot;BFC步向新主城及小蕉对群组服的探索&quot;">​</a></h4><blockquote><p>2020年3月，怪杰在建造自己粉丝服时，误将主城点燃，与小蕉抢救了近半小时，保住了其主体。</p></blockquote><p>2020年5月，怪杰粉丝服并入BFC，成立不拿拿怪杰粉丝服务器。</p><p>同年10月，BFC升级至1.16.1，小蕉设计了第二版主城（图2-2）。</p><blockquote><p><img src="'+l+'" alt="">图2-2 第二版主城(2021-2022.5关服使用)</p></blockquote><p>该主城还是有较大模仿性，雕像岛、解谜、传送门岛、甚至货币、钱袋都模仿了白一粉丝服。（雕像岛后被枫林拆除）</p><p>不久，小蕉从云启之域获得灵感，成立了蕉拿之蒙群组服，包括空岛服、生存服、创造服、模组服、饥饿服、搭路服等，但最终没有亮相。</p><div class="danger custom-block"><p class="custom-block-title">💡小提示</p><p>实际上，小蕉还规划了BMC（模组服）、BVC（动森服）、BGTAC（FiveM）、BRC（RedM），但全部弃坑。</p></div><h2 id="第二单元-bfc一周目的开始与更名云琉世界" tabindex="-1">第二单元 BFC一周目的开始与更名云琉世界 <a class="header-anchor" href="#第二单元-bfc一周目的开始与更名云琉世界" aria-label="Permalink to &quot;第二单元 BFC一周目的开始与更名云琉世界&quot;">​</a></h2><h3 id="第3课-bfc的正式开服与巩固" tabindex="-1">第3课 BFC的正式开服与巩固 <a class="header-anchor" href="#第3课-bfc的正式开服与巩固" aria-label="Permalink to &quot;第3课 BFC的正式开服与巩固&quot;">​</a></h3><blockquote><p>“哈喽大家好我是不拿拿，不知道大家有没有想过，拥有一台属于自己的Minecraft服务器是什么样的体验呢?” ——《某小学生UP主开了一个Minecraft服务器给粉丝玩？》</p></blockquote><h4 id="正式开服前的准备" tabindex="-1">正式开服前的准备 <a class="header-anchor" href="#正式开服前的准备" aria-label="Permalink to &quot;正式开服前的准备&quot;">​</a></h4><p>2021年8月，小蕉为服务器购买了新机器(配置X5670+16G，X58主版)，安装过程中出现了买错内存、装错系统等问题，但最终成功。新机器的组建标志着BFC由虚拟向实体的转变。</p><p>10月，服务器升级至1.16.5，并正式开服。不久，又升级至1.17.1。</p><h4 id="开服后经历的辉煌" tabindex="-1">开服后经历的辉煌 <a class="header-anchor" href="#开服后经历的辉煌" aria-label="Permalink to &quot;开服后经历的辉煌&quot;">​</a></h4><p>开服后，服内涌入一定数量的玩家（QQ群涨至150多人），最高服内同时在线 达8人。服务器收到了上百份白名单申请，且大多数来自浙江、江苏、广东三省。</p><p>11月，服务器开始7×24运行。不久，夜月喵嘟服主喵喵找到小蕉，决定与BFC展开合作。合作为服务器提供了更多玩家，且未来夜服的一位玩家千秋还成为了BFC核心管理成员。</p><p>12 月，蕉拿之蒙群组服与BFC合并，BFC成为蕉拿之蒙主服。</p><p>2022年初，怪杰提议将 “蕉拿之蒙” 改名为琉光世界，但后来改变了主意。</p><p>暮白熊服案是服务器开服以来较有代表性的玩家熊服事件，众管理决定将其封禁并踢出群组，但小蕉决定给予他改过自新的机会，没有封禁他。事实证明，小蕉的决策是明智的。如今暮白已是服务器内部组骨干成员，并成立了自己的SBNServer。</p><p>此外，服务器对管理员违规案的处理也有落实。在一周目期间，服务器对两位违规管理员StarTie233与天皓进行撤职处理(2024年，StarTie233因表现良好，被重新纳入管理组)。</p><p>2022年3月，在怪杰提议下，服务器更名云琉世界（YunLiuCraft，YLC）。</p><h3 id="第4课-云琉世界一周目的落幕与二周目的筹备" tabindex="-1">第4课 云琉世界一周目的落幕与二周目的筹备 <a class="header-anchor" href="#第4课-云琉世界一周目的落幕与二周目的筹备" aria-label="Permalink to &quot;第4课 云琉世界一周目的落幕与二周目的筹备&quot;">​</a></h3><h4 id="云琉世界一周目的落幕" tabindex="-1">云琉世界一周目的落幕 <a class="header-anchor" href="#云琉世界一周目的落幕" aria-label="Permalink to &quot;云琉世界一周目的落幕&quot;">​</a></h4><p>2022年5月，小蕉在 QQ 群中发布公告：“由于本人将要备战小升初考试，服务器将暂时停服。”</p><p>2022年5月，小蕉为了备战小升初考试，于是把服务器移至 huangyu_id的机器上。不久，小蕉宣布服务器将暂时停服，但承诺会在暑假为大家带来全新的二周目。</p><p>后来，huangyu_id去备战中考，也关闭了自己的机器。此后 huangyu_id 再也没有出现过，小蕉也丢失了原本一周目的存档。现可见的存档示意图为日后小蕉凭记忆所画（图 4-1）。</p><blockquote><p><img src="'+h+'" alt="">图4-1 一周目存档</p></blockquote><h4 id="对云琉世界一周目的评价" tabindex="-1">对云琉世界一周目的评价 <a class="header-anchor" href="#对云琉世界一周目的评价" aria-label="Permalink to &quot;对云琉世界一周目的评价&quot;">​</a></h4><p>云琉世界一周目的开服，是其发展历史上的重要里程碑。它既是小蕉跨服务器领域长期尝试的重要成果，也是推动云琉世界后续发展的强力涌流。云琉世界一周目开服，开启了一个崭新的局面。</p><h4 id="二周目的筹备与失败" tabindex="-1">二周目的筹备与失败 <a class="header-anchor" href="#二周目的筹备与失败" aria-label="Permalink to &quot;二周目的筹备与失败&quot;">​</a></h4><p>2022年7月，服务器二周目开始建设，版本升级到1.18.2。小蕉设计了第三版主城（图 4-2）。</p><blockquote><p><img src="'+p+'" alt="">图4-2 第三版主城(原定二周目)</p></blockquote><p>8月底，服务器二周目在匆忙的建设后，没有经过任何检测，就实行了开服。开服不及10日，便遇到了致命性错误，服务器多次崩端。无奈之下，小蕉关闭服务器，被迫宣布云琉世界进入无限期停服。云琉世界二周目失败。</p><h2 id="第三单元-云琉世界对新式运营与玩法的探索" tabindex="-1">第三单元 云琉世界对新式运营与玩法的探索 <a class="header-anchor" href="#第三单元-云琉世界对新式运营与玩法的探索" aria-label="Permalink to &quot;第三单元 云琉世界对新式运营与玩法的探索&quot;">​</a></h2><h3 id="第5课-云琉世界主城互动化探索与内阁组建" tabindex="-1">第5课 云琉世界主城互动化探索与内阁组建 <a class="header-anchor" href="#第5课-云琉世界主城互动化探索与内阁组建" aria-label="Permalink to &quot;第5课 云琉世界主城互动化探索与内阁组建&quot;">​</a></h3><blockquote><p>2022年底，小蕉看到了《幻塔》最新地图镜都的视频，其震撼感极强，互动性玩法也十分丰富，由此小蕉萌生了主城互动化的想法。</p></blockquote><h4 id="对主城新形式的探索" tabindex="-1">对主城新形式的探索 <a class="header-anchor" href="#对主城新形式的探索" aria-label="Permalink to &quot;对主城新形式的探索&quot;">​</a></h4><p>2022年 11月，小蕉从幻塔主城当中获得灵感，设计了第四版主城（图 5-1）。</p><blockquote><p><img src="'+c+'" alt="">图5-1 第四版主城(灵感来自幻塔镜都)</p></blockquote><p>该版主城以赛博与国风结合为基础设计，在对幻塔建筑部分模仿之外，还有许多原创元素。</p><p>其中水池也可作舞台，背景是一个YLC的LOGO，商业街部分为国风大于赛博风，城市整体呈国风赛博风格，空中还有模仿镜都空中出租车的 “过山车”。</p><p>但是，建造国风赛博的难度过大，受限于技术，如果技术力不够，无法做到完美融合，所以部分人提出了质疑。</p><h4 id="云琉世界及其集团的整理" tabindex="-1">云琉世界及其集团的整理 <a class="header-anchor" href="#云琉世界及其集团的整理" aria-label="Permalink to &quot;云琉世界及其集团的整理&quot;">​</a></h4><p>2023年2月，YunliuStudio正式成立。小蕉对团队进行了大规模的整合、整理，合并原BCServer与BSV，设 YunliuGame、YunliuMedia、YunliuNetwork、YunliuCraft 四个部门；其中在 YunliuCraft 部门中设立了包括核心组、RPG 组、玩法组、生存组在内的几个小组，核心组为总领导。云琉世界被确立为半公益半商业服务器。</p><p>在这些部门中，早期发展最受重视的为早期 RPG 组，天启组织三味书屋、千秋建立 RPG 组，并命名 RPG 服为 “蕉叶阁”；千秋、天启、三味书屋分别负责剧情编写、建筑及音乐、策划工作。但是，由于时间与学业等方面问题，RPG在2023年4月弃项。</p><h4 id="枫林事件" tabindex="-1">“枫林事件” <a class="header-anchor" href="#枫林事件" aria-label="Permalink to &quot;“枫林事件”&quot;">​</a></h4><p>2023年2月，小蕉将自己设计的第四版主城交给服务器第一建筑师枫林，枫林自加入服务器以来，在主城及多处建筑上付出大量劳动，其建筑能力得到管理组一致认可，故获第一建筑师之职。枫林承诺在本年暑假提供成果。</p><p>2023年7月，小蕉收到了枫林提供的“成果”。小蕉询问设计图中的部分在哪，对方称“忘记了”。小蕉进一步在地图中发现水印，经搜索后证实为一国外建筑团队的水印。小蕉前去质问，枫林声称自己是找人完成，并不知情，并承诺自己将亲自建造。</p><p>2023年11月，枫林退出群聊，并删除所有有关人员的QQ，枫林事件自此爆发。</p><p>截至2026年7月，此次事件的具体真相仍未能完全厘清。可以确定的是：作为服务器第一建筑师，枫林交付的成果中包含国外建筑团队的素材，且未能澄清其具体来源。无论找人完成之说是否属实，作为主城建设的第一责任人，枫林都负有不可推卸的审核失职之责。</p><p>“枫林事件” 充分展示了 “凡事都得靠自己” 的道理。虽然这次事件让服务器建设沉重地受到打击，小蕉一度陷入绝望，并发表 “跑路得了”“服务器开个鸡” 等言论。但经过调整，DDM 决定与小蕉一同建设主城。小蕉及时发现地图为盗取，为服务器及服主个人名誉挽回了损失，也为 “龙渊计划” 的进行拉开了序幕。</p><p>枫林前期为服务器主城及多处建筑付出的劳动不容抹杀；但其作为第一建筑师，在交付成果中未能澄清国外团队素材的来源、且在承诺亲自建造后退出断联，这一行为构成了云琉世界史上最严重的信任危机之一。功过各表，以待后人评说。</p><h3 id="第6课-龙渊计划的发展与挫折" tabindex="-1">第6课 龙渊计划的发展与挫折 <a class="header-anchor" href="#第6课-龙渊计划的发展与挫折" aria-label="Permalink to &quot;第6课 龙渊计划的发展与挫折&quot;">​</a></h3><blockquote><p>2024年，小蕉在B站观赏了国家建筑师团队的作品《淘宝城》，大受震撼，于是绘下了 “赛博龙渊”。</p></blockquote><h4 id="龙渊计划的开端" tabindex="-1">龙渊计划的开端 <a class="header-anchor" href="#龙渊计划的开端" aria-label="Permalink to &quot;龙渊计划的开端&quot;">​</a></h4><p>2024年1月，小蕉由《淘宝城》启发，以现实中的浙江省龙泉市为原型，设计了服务器第五版主城——龙渊城。不久之后又进行修改，最终呈现的是第七版主城（图6-1）。</p><blockquote><p><img src="'+n+'" alt="">图6-1 第七版主城</p></blockquote><p>该版主城为完全原创。西街原型为现实龙泉西街；高铁站原型龙泉市站；超市原型现代商业广场；瓷溪川小镇原型望瓯·陶溪川；汽车工厂原型吉利工厂；商场原型万达广场；互联网城原型为城南 CBD；未来社区原型为水南未来社区。第五至七版主城的设计推出，标志着云琉世界主城实现了从模仿到原创的历史性飞跃。</p><h4 id="龙渊计划-的发展与挫折" tabindex="-1">“龙渊计划”的发展与挫折 <a class="header-anchor" href="#龙渊计划-的发展与挫折" aria-label="Permalink to &quot;“龙渊计划”的发展与挫折&quot;">​</a></h4><p>2024年2月，服务器内部组开始扩招，以应对龙渊计划，预计在2024 年暑假开服，服务器升级为1.20.1。</p><p>4月13日，DFish、Young在建设主城时，由于DFish的失误，误将陶瓦（Terracotta）填充为 TNT，造成了商业街大爆炸，Young的作品几乎被毁。且小蕉的反应不够及时，以及后续小蕉因着急的操作失误（最初误以为是CMI插件的问题，后续复盘才发现真相），导致损失最大化。在众人抢救下，商业街80%被修复。这次事件是云琉世界建设当中的一次严重错误，严重打击了Young建造的积极性。这件事史称四・一三商业街大爆炸。</p><p>2024年年底，主城建设70%完成。</p><div class="danger custom-block"><p class="custom-block-title">水立方</p><p>水立方是由Deep设计并搭建的一个标志性艺术建筑。尽管外观与水立方没有任何关系，它的名字依然是水立方。</p></div><h4 id="云琉世界暑假服" tabindex="-1">云琉世界暑假服 <a class="header-anchor" href="#云琉世界暑假服" aria-label="Permalink to &quot;云琉世界暑假服&quot;">​</a></h4><p>2024年7月，云琉世界正式服未完工，为补偿期待已久的玩家，小蕉开放了云琉世界暑假服供众人游玩。以三味书屋、DADA、Yangzhixiang为代表的玩家在服内创造了“云城新区”“云岛工业区” 以及超级公路网的奇迹。这激发了玩家积极性，为正式开服打下了精神基础。</p><div class="danger custom-block"><p class="custom-block-title">Yangzhixiang纪念馆</p><p>2024年，服务器元老成员 Yangzhixiang 因不明原因退服，为纪念他，小蕉委托DADA为他建造了一个纪念馆。2026 年 7 月，Yangzhixiang回归。</p></div><h4 id="客城计划" tabindex="-1">“客城计划” <a class="header-anchor" href="#客城计划" aria-label="Permalink to &quot;“客城计划”&quot;">​</a></h4><p>2024年10月，小蕉对原主城龙渊城存在不满，如主城风格不对应（想要国风，结果不是）、建筑比例大小失衡，没有达到赛博朋克效果等。于是，小蕉决定启动“客城计划”，建设一个以广东省梅州市、广东省深圳市为原型的巨型城市——客城，作为一个更高互动性的主城。计划启动后，立刻遭到多人的反对，最终在多方面权衡下，小蕉取消了该计划，决定将发展重心放在龙渊计划上。</p><p>这次计划是一个由服主错误发起、天方夜谭的计划。服主忽视了服务器发展水平与内部组能力与精力水平，且对该计划充满了理想色彩，想法过于超前。</p><h2 id="第四单元-服务器临近开服的善后工作" tabindex="-1">第四单元 服务器临近开服的善后工作 <a class="header-anchor" href="#第四单元-服务器临近开服的善后工作" aria-label="Permalink to &quot;第四单元 服务器临近开服的善后工作&quot;">​</a></h2><h3 id="第7课-机器的更换与政治协商会议" tabindex="-1">第7课 机器的更换与政治协商会议 <a class="header-anchor" href="#第7课-机器的更换与政治协商会议" aria-label="Permalink to &quot;第7课 机器的更换与政治协商会议&quot;">​</a></h3><blockquote><p>2025 年 6 月，小蕉前往杭州参加研学，回来后发现原本的机器彻底无法开机，经排查初步确定主板或电源出了问题。这台机器在服役4年后，寿终正寝。</p></blockquote><h4 id="旧机器的退役与新机器的到来" tabindex="-1">旧机器的退役与新机器的到来 <a class="header-anchor" href="#旧机器的退役与新机器的到来" aria-label="Permalink to &quot;旧机器的退役与新机器的到来&quot;">​</a></h4><p>2025年6月，服务器旧机器彻底无法使用。于是小蕉开始筹备新机器。</p><p>8月，Admire思慕决定换新电脑，于是将旧电脑(i5-11400+32G+4TB) 捐给服务器当做新机器，小蕉仅支付邮费。</p><h4 id="政治协商会议的召开" tabindex="-1">政治协商会议的召开 <a class="header-anchor" href="#政治协商会议的召开" aria-label="Permalink to &quot;政治协商会议的召开&quot;">​</a></h4><p>2025年7月，云琉世界第一届政治协商会议在主城服主府隆重召开。本次会议的参与者有小蕉、DDMTDXW、暮白、千秋。会议持续约40分钟，众人将服务器未完工项目列表进行整理。会议上，众人还作出实行轻量化改革的决策，即删除一切多余插件与玩法，从200+插件缩减至100+个，并将原 “半公益半商业” 的性质转变为 “公益” 性质，并长期不变。众人删除了所有 RMB 付费内容，包括VIP、权限购买、时装购买等，并保证由游戏币获取相关物品（称号等）。</p><p>云琉世界第一届政治协商会议的召开，作出了实行轻量化改革的伟大决策，标志着服务器向公益服的转变，减轻了建设负担，提高了建设效率，是云琉世界停服以来具有深刻意义的伟大转折，为云琉世界的开服作了必要准备。</p><div class="danger custom-block"><p class="custom-block-title">💡学习聚焦</p><p>2025年7月，小蕉花50元委托B站UP树儿帮助改造主城，重点改造“西街”，探险家中心等建筑，使主城内的样貌焕然一新，众人十分满意。</p></div><h3 id="第8课-wiki的开放与约法的制定" tabindex="-1">第8课 WIKI的开放与约法的制定 <a class="header-anchor" href="#第8课-wiki的开放与约法的制定" aria-label="Permalink to &quot;第8课 WIKI的开放与约法的制定&quot;">​</a></h3><blockquote><p>经过4个月的搭建，云琉世界的WIKI在2025年11月向公众开放。2026年初，约法也得到制定，这都为服务器开服做了重要准备。</p></blockquote><h4 id="wiki-的开放" tabindex="-1">WIKI 的开放 <a class="header-anchor" href="#wiki-的开放" aria-label="Permalink to &quot;WIKI 的开放&quot;">​</a></h4><p>2025年11月，小蕉将WIKI对外开放，发布了第一版本的完善WIKI。WIKI包含了主城介绍、玩法介绍、玩法教程、服务器历史、成员介绍等多个板块，其目的是让玩家提前熟悉服务器内容，另一方面还可以向公众证明——云琉世界的建设已取得重要成果。</p><h4 id="玩家约法的制定" tabindex="-1">玩家约法的制定 <a class="header-anchor" href="#玩家约法的制定" aria-label="Permalink to &quot;玩家约法的制定&quot;">​</a></h4><p>2026年1月2日，小蕉编写并发布了《云琉世界玩家约法》，成为继《云琉世界玩家守则》《云琉世界管理守则》后云琉世界第三部成文法案，该法案有着统领全局的作用，规定了云琉世界最基本的原则。</p><p>其中，云琉世界的立服之本为：不限制年龄，无正版验证，服务器禁止一切形式的年龄歧视与非正版歧视。</p><p>开服宗旨为：只为打造一个和谐的Minecraft社区。</p><p>还明确了管理员职权、玩家管理、玩家大会等相关内容，并明确服务器内一切内容必须遵循我国所有法律与浙江省省级规定。</p><p>玩家约法的制定，使云琉世界基本的原则有了规定，云琉世界规则体系进一步完善。</p><h4 id="mcdr的安装" tabindex="-1">MCDR的安装 <a class="header-anchor" href="#mcdr的安装" aria-label="Permalink to &quot;MCDR的安装&quot;">​</a></h4><p>2026年1月7日，为了开服后能够更好地对服务器实行管理与备份，小蕉与暮白为服务端装上了MCDReforged。</p><div class="danger custom-block"><p class="custom-block-title">主城的部分改造</p><p>2026年1月，小蕉、KING、牢段、DADA对服务器主城的一些遗留性问题进行改造。其中，众人将服主府改为了半国风；小蕉改造了 LEENZHI酒店和瓷溪川小镇；DADA新建了“西街”的两个建筑。这些改造使主城设计更加协调，主城更加美观。</p></div><h3 id="第9课-主城视频的爆火与内测的开启" tabindex="-1">第9课 主城视频的爆火与内测的开启 <a class="header-anchor" href="#第9课-主城视频的爆火与内测的开启" aria-label="Permalink to &quot;第9课 主城视频的爆火与内测的开启&quot;">​</a></h3><blockquote><p>“大概是（20）24年的时候，我在给服务器设计主城，就想到了……” ——《龙泉新闻》</p></blockquote><h4 id="主城视频爆火" tabindex="-1">主城视频爆火 <a class="header-anchor" href="#主城视频爆火" aria-label="Permalink to &quot;主城视频爆火&quot;">​</a></h4><p>2026年2月14日，小蕉将主城剪辑成视频发布到抖音，一经发布就获得大量观众。截至7月30日，该视频已有13.3万的浏览量。2月 24日，小蕉接受当地电视台龙泉新闻的采访，并登上龙泉新闻的官方抖音号。这是开服前云琉世界尝试拓广宣传渠道的一大成功，提高了小蕉及云琉世界的名声，为云琉世界正式开服奠定了基础。</p><h4 id="服务器内测的开启" tabindex="-1">服务器内测的开启 <a class="header-anchor" href="#服务器内测的开启" aria-label="Permalink to &quot;服务器内测的开启&quot;">​</a></h4><p>2026年2月19日中午12:00，小蕉宣布云琉世界二周目不删档测试正式启动。本次内测是在基于服务器绝大部分内容已完工而开启的长期性能性测试，预计持续到2026年8月，8月将正式开服，虽然还不能肯定，但也相差无几。</p><p>在内测刚开始的几天，Yuesekaer、awashen、开场白、怪杰、云默安、SKY、千秋、暮白、星思、YanLH、三味书屋等成员都加入了内测。在游玩测试持续进行的情况下，剩余未完工内容也有了进展。主城自定义饮品、西街部分店铺、火车站和机场的内饰与周边造景、NPC配置等一系列工作都在进行。YanLH完善了主城商店；Yuesekaer负责NPC配置、火车站与机场的内饰及周边造景；SKY 负责部分建筑的内饰；小蕉负责饮品系统等一系列内容统筹工作；暮白等多人负责性能问题分析与解决。</p><p>总的来说，这次内测是自2022年停服以来至正式开服前的一次最重要的里程碑，它证明了YLC成员4年来努力奋斗取得的累累硕果，是云琉世界开服准备中的必然历程。这次内测激发了服内成员的积极性，也增强了大家对云琉世界未来的信心，更为云琉世界的正式开服奠定了极为坚实的基础。云琉世界必将重启，也必然重启！</p><p>2026年2月25日，暮白被小蕉任命为云琉世界代理服主。6月18日，暮白为服务器安装了MCSManager。</p><p>2026年7月29日，小蕉组建云琉世界开服应急小分队，以应对开服前的所有难题。</p>',119)]))}const f=e(s,[["render",d]]);export{C as __pageData,f as default};
